protocol Describable {
    var description: String { get }
}
struct Item: Describable {
    let description: String
}
let item = Item(description: "Coffee Mug")
print(item.description)

protocol Resettable {
    mutating func reset()
}
struct ScoreTracker: Resettable {
    var points = 100
    mutating func reset() { points = 0 }
}
var tracker = ScoreTracker()
tracker.reset()
print(tracker.points)

protocol ValueProvider {
    var value: Int { get }
}
class ProviderA: ValueProvider { var value: Int { 10 } }
class ProviderB: ValueProvider { var value: Int { 20 } }
let list: [any ValueProvider] = [ProviderA(), ProviderB()]
let total = list.reduce(0) { $0 + $1.value }
print(total)

protocol Incrementable {
    var step: Int { get }
    func nextValue(after current: Int) -> Int
}
struct StepCounter: Incrementable {
    var step: Int { 5 }
    func nextValue(after current: Int) -> Int { current + step }
}
let counter = StepCounter()
print(counter.nextValue(after: 10))

protocol Named { var name: String { get } }
protocol Aged { var age: Int { get } }
struct Person: Named, Aged {
    var name: String
    var age: Int
}
func display(person: Named & Aged) -> String {
    "\(person.name): \(person.age)"
}
let p = Person(name: "Alex", age: 28)
print(display(person: p))

protocol Delegate: AnyObject {
    func didComplete()
}
class Master: Delegate {
    func didComplete() { print("Done") }
}
class Task {
    weak var delegate: Delegate?
    func finish() { delegate?.didComplete() }
}
let m = Master()
let t = Task()
t.delegate = m
t.finish()

protocol Initializable {
    init(identifier: String)
}
final class Entity: Initializable {
    var identifier: String
    init(identifier: String) { self.identifier = identifier }
}
let e = Entity(identifier: "UUID-101")
print(e.identifier)

protocol Calculable {
    static func add(_ a: Int, _ b: Int) -> Int
}
struct Calculator: Calculable {
    static func add(_ a: Int, _ b: Int) -> Int { a + b }
}
print(Calculator.add(14, 28))

